$root = (Get-Location).Path

$b = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes("$root\build-api.mjs", $b)
Write-Host "OK build-api.mjs (output em api/)" -ForegroundColor Green

$b = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes("$root\vercel.json", $b)
Write-Host "OK vercel.json (functions: api/**/*.js)" -ForegroundColor Green

git add -A
git commit -m "fix: esbuild compila api/*.ts para api/*.js no mesmo diretório"
git push origin main
Write-Host "Deploy disparado!" -ForegroundColor Green
